        <tbody><tr><td>Golf irrigation reduction</td><td class="val">20&ndash;40%</td></tr><tr><td>Pool water reduction (backwash + make-up)</td><td class="val">15&ndash;30%</td></tr><tr><td>Marina dock reclassification</td><td class="val">$8&ndash;20K/yr</td></tr><tr><td>Annual club saving (18-hole + full amenity)</td><td class="val">$30&ndash;75K</td></tr><tr><td>Billing audit recovery</td><td class="val">8&ndash;12% of total bill</td></tr><tr><td>Payback period</td><td class="val">8&ndash;14 months</td></tr></tbody>
